type Style = { [key: string]: string | Style };

function merge(...styles: (Style | undefined)[]): Style {
  const out: Style = {};
  for (const style of styles)
    for (const [k, v] of Object.entries(style ?? {}))
      out[k] =
        typeof v === 'object' && typeof out[k] === 'object'
          ? merge(out[k] as Style, v)
          : v;
  return out;
}

/** The complete style for one set of props, for `sx` or `styleOverrides.root`. */
export function solarTrendBadgeStyle(props: SolarTrendBadgeProps = {}): Style {
  const p: Record<string, unknown> = { ...solarTrendBadgeDefaults };
  for (const [k, v] of Object.entries(props)) if (v !== undefined) p[k] = v;
  const key = `type=${p.type}`;
  const s = solarTrendBadgeStyles as unknown as {
    reset: Style;
    root: Style;
    sizes: Record<string, Style>;
    appearances: Record<string, Style>;
    combined: Record<string, Record<string, Style>>;
  };
  const size = p.size as string;
  return merge(
    s.reset,
    s.root,
    s.sizes[size],
    s.appearances[key],
    s.combined[size]?.[key],
  );
}

/** A drawn layer's outline: its box, and the fill's and the stroke's paths (Figma's geometry). */
type Glyph = {
  width: number;
  height: number;
  fill: { d: string; evenOdd: boolean }[];
  stroke: { d: string; evenOdd: boolean }[];
};
/** One layer's composition: shown or not, its composed child, its glyph, its position. */
export type SolarTrendBadgeParts = Record<
  string,
  string | number | boolean | Glyph | null
>;
type Parts = SolarTrendBadgeParts;
type Layered = {
  base: Parts;
  size?: Record<string, Parts>;
  appearance?: Record<string, Record<string, Parts>>;
  combined?: Record<string, Record<string, Record<string, Parts>>>;
};

/**
 * What the shell renders for one set of props in one state, by layer: whether it shows, and which
 * component and variant a composed child takes. The same precedence as the style: base, size,
 * appearance, then size and appearance together, each at rest and then in the state.
 */
export function solarTrendBadgeCompose(
  props: SolarTrendBadgeProps = {},
  state: string = 'default',
): Record<string, Parts> {
  const p: Record<string, unknown> = { ...solarTrendBadgeDefaults };
  for (const [k, v] of Object.entries(props)) if (v !== undefined) p[k] = v;
  const key = `type=${p.type}`;
  const size = p.size as string;
  const out: Record<string, Parts> = {};
  for (const [layer, c] of Object.entries(
    solarTrendBadgeComposition as unknown as Record<string, Layered>,
  )) {
    const states = state === 'default' ? ['default'] : ['default', state];
    out[layer] = Object.assign(
      {},
      c.base,
      c.size?.[size],
      ...states.flatMap((st) => [
        c.appearance?.[key]?.[st],
        c.combined?.[size]?.[key]?.[st],
      ]),
    );
  }
  return out;
}

